package ascache

import "time"

// LoadConfig is a configuration object that used by the Load() method.
// It is generated by combining a default value with any functional
// options that are passed to the Load() method.
type LoadConfig struct {
	mode            string
	databaseTimeout time.Duration
	fetchTimeout    time.Duration
	minAge          time.Duration
}

// LoadOption is a functional option that can be passed to the Load() method.
type LoadOption func(*LoadConfig)

// NewLoadConfig creates a new LoadConfig object, and applies any functional options that are passed to it.
func NewLoadConfig(options ...any) LoadConfig {

	// A forced reload is something a remote peer can provoke, so the cooldown is on by default and a
	// caller that genuinely needs an uncapped refresh opts OUT with WithMinAge(0). (BUG-22)
	result := LoadConfig{
		mode:            CacheModeReadWrite,
		databaseTimeout: defaultDatabaseTimeout,
		fetchTimeout:    defaultFetchTimeout,
		minAge:          defaultMinAge,
	}

	result.With(options...)
	return result
}

// tryCache returns TRUE if the system should check the cache before loading an HTTP resource
func (config LoadConfig) tryCache() bool {
	return config.isReadAllowed() || config.hasMinAge()
}

// isReadAllowed returns TRUE when this config permits the normal (freshness-checked) cache read.
func (config LoadConfig) isReadAllowed() bool {
	return config.mode != CacheModeWriteOnly
}

// notReadAllowed returns TRUE when this config forbids the normal (freshness-checked) cache read.
func (config LoadConfig) notReadAllowed() bool {
	return !config.isReadAllowed()
}

// IsWriteOnly returns TRUE when this config bypasses the cached copy and forces a reload.
func (config LoadConfig) IsWriteOnly() bool {
	return config.mode == CacheModeWriteOnly
}

// isWriteAllowed returns TRUE when this config permits writing the origin's response back to the cache.
func (config LoadConfig) isWriteAllowed() bool {
	return config.mode != CacheModeReadOnly
}

// hasMinAge returns TRUE when this config sets a cooldown before the origin may be contacted again.
func (config LoadConfig) hasMinAge() bool {
	return config.minAge > 0
}

// With applies functional options to the LoadConfig object
func (config *LoadConfig) With(options ...any) {
	for _, option := range options {
		if typed, ok := option.(LoadOption); ok {
			typed(config)
		}
	}
}

// WithDatabaseTimeout is a functional option that sets the budget for each database
// phase of a load: the cache read, and the cache write.
func WithDatabaseTimeout(timeout time.Duration) LoadOption {

	// This is PER PHASE, not per call. A single budget spanning both phases would be
	// spent by the HTTP fetch that runs between them, which does not share it.
	return func(config *LoadConfig) {
		config.databaseTimeout = timeout
	}
}

// WithFetchTimeout is a functional option that sets the budget for the outbound HTTP
// fetch that runs when the cache cannot answer.
func WithFetchTimeout(timeout time.Duration) LoadOption {
	return func(config *LoadConfig) {
		config.fetchTimeout = timeout
	}
}

// WithReadWrite is a functional option that sets the cache mode to READWRITE.
func WithReadWrite() LoadOption {
	return func(config *LoadConfig) {
		config.mode = CacheModeReadWrite
	}
}

// WithReadOnly is a functional option that sets the cache mode to READONLY.
// By skipping WRITE steps, this mode only reads existing cache values and will not
// create or update any cache entries.
func WithReadOnly() LoadOption {
	return func(config *LoadConfig) {
		config.mode = CacheModeReadOnly
	}
}

// WithWriteOnly is a functional option that sets the cache mode to WRITEONLY.
// By skipping READ steps, this mode flushes any existing cache values and writes new values only.
func WithWriteOnly() LoadOption {
	return func(config *LoadConfig) {
		config.mode = CacheModeWriteOnly
	}
}

// WithMinAge is a functional option that sets the cooldown on a forced (WRITEONLY) reload: an entry
// younger than minAge is returned as-is instead.  WithMinAge(0) removes the cooldown entirely.
func WithMinAge(minAge time.Duration) LoadOption {

	// Refetching a document we pulled seconds ago cannot produce a different answer, so the only
	// thing it produces is an outbound request. That matters because the caller that forces a
	// reload here does so in response to a FAILED signature -- something an attacker can trigger at
	// will, naming any keyId host they like. The cooldown caps that at one fetch per minAge. (BUG-22)
	return func(config *LoadConfig) {
		config.minAge = minAge
	}
}
